solucion_referencia:
class Solution:
    def minQueenMoves(self, source: list[int], target: list[int]) -> int:
        dr, dc = abs(source[0] - target[0]), abs(source[1] - target[1])
        if dr == 0 and dc == 0: return 0
        return 1 if dr == 0 or dc == 0 or dr == dc else 2

